/**
 * dsh-we-wallpaper client styles — injected as plain <style> tags by the
 * client apply() (no CSS modules in this bundle). Everything rides the
 * shell's --dsw-alias-* tokens (with neutral fallbacks) so the card matches
 * any base theme, and the layer keeps its own fixed positioning.
 */
/** The background layer element id (see src/client/layer.ts). */
export declare const LAYER_ID = "dsh-we-wallpaper-layer";
/** Body attribute marking the plugin active (dispose removes it). */
export declare const BODY_ATTR = "data-dsh-we-wallpaper";
/** Static CSS for the fixed background layer. */
export declare const LAYER_CSS = "#dsh-we-wallpaper-layer {\n  position: fixed;\n  inset: 0;\n  z-index: -1;\n  overflow: hidden;\n  pointer-events: none;\n  background: #000;\n}\n#dsh-we-wallpaper-layer > video,\n#dsh-we-wallpaper-layer > img,\n#dsh-we-wallpaper-layer > iframe {\n  display: block;\n  width: 100%;\n  height: 100%;\n  object-fit: var(--dsw-we-fit, cover);\n  border: 0;\n  background: transparent;\n  /* The plugin-owned SVG sharpen filter; none when sharpen = 0. */\n  filter: var(--dsh-we-filter, none);\n}\n#dsh-we-wallpaper-layer > iframe {\n  pointer-events: none;\n}\nbody[data-dsh-we-wallpaper] {\n  background-color: #000;\n}\n";
/** Static CSS for the settings card. */
export declare const CARD_CSS = ".dsh-we-card {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  padding: 4px 2px;\n}\n.dsh-we-card-head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n.dsh-we-card-status {\n  font-size: 12px;\n  opacity: 0.75;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  max-width: 100%;\n}\n.dsh-we-card-controls {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));\n  gap: 10px 16px;\n}\n.dsh-we-card-control {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.dsh-we-card-control label {\n  font-size: 12px;\n  opacity: 0.85;\n}\n.dsh-we-card-control input[type='range'] {\n  width: 100%;\n}\n.dsh-we-card-check {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 12px;\n  opacity: 0.9;\n  cursor: pointer;\n}\n.dsh-we-card-search input {\n  width: 100%;\n  box-sizing: border-box;\n  padding: 6px 10px;\n  border-radius: 6px;\n  border: 1px solid var(--dsw-alias-border-l2, rgba(120, 130, 150, 0.35));\n  background: var(--dsw-alias-bg-layer-2, rgba(240, 242, 246, 0.9));\n  color: var(--dsw-alias-label-primary, #1c2430);\n}\n.dsh-we-card-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(132px, 1fr));\n  gap: 10px;\n  max-height: 420px;\n  overflow-y: auto;\n  padding: 2px;\n}\n.dsh-we-card-item {\n  position: relative;\n  border-radius: 8px;\n  overflow: hidden;\n  border: 2px solid var(--dsw-alias-border-l2, rgba(120, 130, 150, 0.3));\n  background: var(--dsw-alias-bg-layer-2, rgba(240, 242, 246, 0.9));\n  cursor: pointer;\n  transition: border-color 0.12s ease, box-shadow 0.12s ease;\n}\n.dsh-we-card-item:hover {\n  border-color: var(--dsw-alias-state-business-primary, #4d6bfe);\n}\n.dsh-we-card-item[data-active='true'] {\n  border-color: var(--dsw-alias-state-business-primary, #4d6bfe);\n  box-shadow: 0 0 0 1px var(--dsw-alias-state-business-primary, #4d6bfe);\n}\n.dsh-we-card-thumb {\n  width: 100%;\n  aspect-ratio: 16 / 9;\n  object-fit: cover;\n  display: block;\n  background: #111;\n}\n.dsh-we-card-thumb-empty {\n  width: 100%;\n  aspect-ratio: 16 / 9;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 11px;\n  opacity: 0.6;\n  background: #1a1f2b;\n  color: #cfd6e4;\n}\n.dsh-we-card-meta {\n  padding: 6px 8px 8px;\n}\n.dsh-we-card-title {\n  font-size: 12px;\n  line-height: 1.35;\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n  color: var(--dsw-alias-label-primary, #1c2430);\n  word-break: break-all;\n}\n.dsh-we-card-badges {\n  display: flex;\n  gap: 4px;\n  margin-top: 4px;\n  flex-wrap: wrap;\n}\n.dsh-we-card-badge {\n  font-size: 10px;\n  line-height: 1;\n  padding: 3px 6px;\n  border-radius: 999px;\n  background: var(--dsw-alias-interactive-bg-hover, rgba(77, 107, 254, 0.1));\n  color: var(--dsw-alias-label-secondary, #4a5568);\n}\n.dsh-we-card-badge[data-hot='true'] {\n  background: var(--dsw-alias-state-warn-primary, #d97706);\n  color: #fff;\n}\n.dsh-we-card-empty {\n  padding: 18px 8px;\n  text-align: center;\n  font-size: 13px;\n  opacity: 0.7;\n  color: var(--dsw-alias-label-secondary, #4a5568);\n}\n";
